"""1319 (#11, stance completion): Record-Coverage-v1318.ps1 with the stance cases, filmed from the peer's free camera and
checked from the partner's presentation state on the observer:
- lean: Y + full side stick, standing then crouched, left and right, then upward peeks (Y + stick up) standing and
  crouched; every trial must present lean weight > .9 with the matching side (or a raised leanUp for peeks) and
  recover (lean weight < .05) before the next;
- stance: stand/crouch changes while stationary, while walking and while turning; the partner's stance mix must cross
  in both directions at least three times each and settle;
- interrupt: a crouched walk interrupted by an attack and by a jump; combat and air presentation must engage and the
  crouched gait must resume, and a final stand.
Generated by make_coverage_v1319.py."""
from pathlib import Path
N = Path(__file__).resolve().parent
src = (N / 'Record-Coverage-v1318.ps1').read_bytes().decode('utf-8')
crlf = '\r\n' in src
s = src.replace('\r\n', '\n')
def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:90])
    s = s.replace(old, new)

rep("[string]$Take='coverage-v1318a',[string]$Candidate='candidate-npc-combat-v1214cf',[string[]]$Sources=@('host','client'),[string[]]$Cases=@('walk8','crouch8','sprint3','turns','startstop','stairs')",
    "[string]$Take='coverage-v1319a',[string]$Candidate='candidate-npc-combat-v1214cf',[string[]]$Sources=@('host','client'),[string[]]$Cases=@('lean','stance','interrupt')")
rep("# 1318 (#11, locomotion completion)", "# 1319 (#11, stance completion): lean (side leans and upward peeks, standing and crouched), stance changes while still,\n# walking and turning, and crouched-walk interruptions. Generated by make_coverage_v1319.py.\n# 1318 (#11, locomotion completion)")
rep("$caseMs=@{walk8=11500;crouch8=13800;sprint3=11000;turns=19000;startstop=16500;stairs=13000}[$case]",
    "$caseMs=@{walk8=11500;crouch8=13800;sprint3=11000;turns=19000;startstop=16500;stairs=13000;lean=20500;stance=15500;interrupt=13500}[$case]")
rep("""    if($case-eq'mana'){
     if($step-eq0-and$t-ge800){C $source 'coop_grant_item mana';$step=1}""",
    """    if($case-eq'lean'){$ln=@(@(0,-32767,0),@(0,32767,0),@(1,-32767,0),@(1,32767,0),@(0,0,32767),@(1,0,32767))
     if($step-lt12){$k=[Math]::Floor($step/2);$at=600+$k*3200
      if($step%2-eq0-and$t-ge$at){$d=$ln[$k];if($k-eq2-or$k-eq5){I $source B 180;Start-Sleep -Milliseconds 400};& "$lab/Send-D2Input.ps1" -Role $source -Button Y -DurationMs 1300 -LeftX $d[1] -LeftY $d[2]|Out-Null;$segments.Add(@{ms=$t;lean=$k;crouched=$d[0];side=[Math]::Sign($d[1]);up=($d[2]-gt0)});$step++}
      elseif($step%2-eq1-and$t-ge$at+1700){& "$lab/Send-D2Input.ps1" -Role $source -DurationMs 350 -LeftY -22000|Out-Null;if($k-eq3){I $source B 180};$step++}}}
    if($case-eq'stance'){$st=@(@(800,'B',0,0),@(2300,'B',0,0),@(3800,'Neutral',13000,0),@(4300,'B',13000,0),@(6300,'B',13000,0),@(8300,'Neutral',0,22000),@(8600,'B',0,22000),@(10600,'B',0,22000),@(12600,'B',0,0),@(13900,'B',0,0))
     if($step-lt$st.Count-and$t-ge$st[$step][0]){$d=$st[$step];$ms=if($d[1]-eq'B'){180}else{1800};& "$lab/Send-D2Input.ps1" -Role $source -Button $d[1] -DurationMs $ms -LeftY $d[2] -RightX $d[3]|Out-Null;$segments.Add(@{ms=$t;stance=$step});$step++}}
    if($case-eq'interrupt'){$it=@(@(600,'B',0,0,180),@(1500,'Neutral',32767,0,2400),@(2600,'Neutral',32767,255,250),@(5000,'Neutral',32767,0,2400),@(6100,'A',32767,0,200),@(9000,'Neutral',32767,0,1500),@(11800,'B',0,0,180))
     if($step-lt$it.Count-and$t-ge$it[$step][0]){$d=$it[$step];& "$lab/Send-D2Input.ps1" -Role $source -Button $d[1] -LeftY $d[2] -RightTrigger $d[3] -DurationMs $d[4]|Out-Null;$segments.Add(@{ms=$t;interrupt=$step});$step++}}
    if($case-eq'mana'){
     if($step-eq0-and$t-ge800){C $source 'coop_grant_item mana';$step=1}""")
rep("""$samples.Add([pscustomobject]@{ms=$t;a=$mv.a;""", """$samples.Add([pscustomobject]@{ms=$t;leanAmount=$mv.leanAmount;leanWeight=$mv.leanWeight;leanUp=$mv.leanUp;airWeight=$mv.airWeight;a=$mv.a;""")
rep("""   if($case-eq'stairs'){C $peer 'coop_observer_camera off'""",
    """   if($case-eq'lean'){$row.leanTrials=@()
    foreach($g in $segments){$w=@($samples|Where-Object {$_.ms-ge$g.ms-and$_.ms-lt$g.ms+1700})
     $ok=if($g.up){@($w|Where-Object {[double]$_.leanWeight-gt.5-and[double]$_.leanUp-gt.2}).Count}else{@($w|Where-Object {[double]$_.leanWeight-gt.9-and[double]$_.leanAmount*$g.side-gt.5}).Count}
     $after=@($samples|Where-Object {$_.ms-ge$g.ms+2400-and$_.ms-lt$g.ms+3100-and[double]$_.leanWeight-lt.05}).Count
     $row.leanTrials+=[ordered]@{trial=$g.lean;crouched=$g.crouched;side=$g.side;up=$g.up;presented=$ok;recovered=$after}
     if(!$ok){throw "Lean trial $($g.lean) not presented"};if(!$after){throw "Lean trial $($g.lean) did not recover"}}
    $row.checks.Add('Partner presented and recovered all 6 lean/peek trials (standing/crouched, left/right, up)')}
   if($case-eq'stance'){$down=0;$upc=0;$prev=$null;foreach($x in $samples){if($prev){if([double]$prev.stanceMix-lt.5-and[double]$x.stanceMix-ge.5){$down++};if([double]$prev.stanceMix-ge.5-and[double]$x.stanceMix-lt.5){$upc++}};$prev=$x}
    $row.toCrouch=$down;$row.toStand=$upc;if($down-lt3-or$upc-lt3){throw "Stance changes presented: to crouch $down, to stand $upc (3 each required)"}
    if([double]$samples[-1].stanceMix-gt.05){throw 'Partner did not settle standing'};$row.checks.Add("Partner stance changes: $down to crouch, $upc to stand, settled")}
   if($case-eq'interrupt'){$cb=@($samples|Where-Object {[double]$_.combatWeight-gt.5}).Count;$air=@($samples|Where-Object {[double]$_.airWeight-gt.5}).Count
    $resumed=@($samples|Where-Object {$_.ms-ge9000-and$_.ms-lt10500-and[double]$_.stanceMix-gt.5-and[double]$_.speed-gt.15}).Count;$row.combatSamples=$cb;$row.airSamples=$air;$row.resumedSamples=$resumed
    if(!$cb-or!$air-or!$resumed){throw "Interruptions: combat $cb, air $air, crouched gait resumed $resumed"};$row.checks.Add('Crouched walk interrupted by attack and jump, then resumed crouched')}
   if($case-eq'stairs'){C $peer 'coop_observer_camera off'""")
rep("if($case-notin'kick','crouchheavy','note','mana','stairs'-and$low.Count-gt3){", "if($case-notin'kick','crouchheavy','note','mana','stairs','interrupt'-and$low.Count-gt3){")
rep("scope='Locomotion completion coverage (1318, #11): walks and crouch walks in 8 directions, sprint and diagonals, in-place turns by size, starts/stops and speed changes, stairs; both source roles, product controller, free camera; checked from the partner presentation state; fixture restored after every case.'",
    "scope='Stance completion coverage (1319, #11): side leans and upward peeks standing and crouched, stance changes while still, walking and turning, crouched-walk interruptions; both source roles, product controller; checked from the partner presentation state; fixture restored after every case.'")
out = s.replace('\n', '\r\n') if crlf else s
